namespace Commerce.Operations.Api.Dashboard;
public static class DashboardEndpoints{public static IEndpointRouteBuilder MapDashboardEndpoints(this IEndpointRouteBuilder endpoints){endpoints.MapGet("/api/dashboard",async(DashboardRepository repository,DashboardGateway gateway)=>{try{var local=await repository.SummaryAsync();var engine=await gateway.GetAsync();return Results.Ok(new OperationsDashboard(local.TotalProducts,local.ActiveProducts,local.TotalCustomers,local.ActiveCustomers,engine.TotalOrders,engine.NetRevenue,engine.OrdersByStatus,engine.AvailableQuantity,engine.ReservedQuantity,engine.LowStockProducts,engine.PendingEvents,DateTime.UtcNow));}catch(DashboardGatewayException e){return Results.Problem(statusCode:(int)e.StatusCode,title:"Order engine request failed",detail:e.Message);}}).RequireAuthorization().WithTags("Dashboard");return endpoints;}}
